import { stdout } from std.io;
class Account {
    private mut balance: Int32 = 0;
    protected mut tag: String = "acct";
    public inmut owner: String;
    construct(owner: String) { this.owner = owner; }
    deposit(n: Int32): Void { this.balance = this.balance + n; }
    get_balance(): Int32 { return this.balance; }
}
class Savings extends Account {
    construct(owner: String) { super(owner); }
    label(): String { return this.tag + ":" + this.owner; }
}
fn main(): Void {
    mut s = Savings("Zed");
    s.deposit(5);
    s.deposit(7);
    stdout.println(s.get_balance());
    stdout.println(s.label());
}
